package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;import java.io.*;
/** Existing mail/maps notifications only; opt-in encrypted digest, never extra speech or network. */
final class NotificationReview {
 static synchronized void observe(Context c,String identity,String kind,String title,String body,int priority,long at){try{if(!c.getSharedPreferences("notification_review",0).getBoolean("enabled",false))return;if(!kind.matches("mail|navigation"))return;String id=RecorderPhotoStore.hash(identity.getBytes("UTF-8"));JSONObject store=ReviewStore.read(c,"notices");JSONArray rows=store.optJSONArray("items"),next=new JSONArray();JSONObject previous=null;if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(id.equals(row.optString("id")))previous=row;else if(row.optLong("at")>=System.currentTimeMillis()-7L*86400000)next.put(row);}String t=title.substring(0,Math.min(160,title.length())),b=body.substring(0,Math.min(1200,body.length()));boolean same=previous!=null&&t.equals(previous.optString("title"))&&b.equals(previous.optString("body"));JSONObject row=new JSONObject().put("id",id).put("kind",kind).put("title",t).put("body",b).put("priority",kind.equals("navigation")?3:priority>=1?2:1).put("at",Math.min(System.currentTimeMillis(),at)).put("read",same&&previous.optBoolean("read")).put("revision",same?previous.optInt("revision",1):previous==null?1:previous.optInt("revision",1)+1);JSONArray bounded=new JSONArray();for(int i=Math.max(0,next.length()-199);i<next.length();i++)bounded.put(next.get(i));bounded.put(row);ReviewStore.write(c,"notices",new JSONObject().put("items",bounded));}catch(Exception e){android.util.Log.w("LokiNotices","local notification digest unavailable");}}
 static synchronized JSONObject list(Context c)throws Exception{JSONObject workspace=ConversationWorkspace.snapshot(c),capture=workspace.optJSONObject("capture"),departure=workspace.optJSONObject("departure");boolean fresh=workspace.optBoolean("connected"),busy=fresh&&(capture!=null&&capture.optBoolean("meetingService")||departure!=null&&departure.optBoolean("navigationActive"));JSONArray rows=ReviewStore.read(c,"notices").optJSONArray("items"),out=new JSONArray();java.util.ArrayList<JSONObject> sorted=new java.util.ArrayList<>();if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject row=new JSONObject(rows.getJSONObject(i).toString());if(row.optLong("at")>=System.currentTimeMillis()-7L*86400000){row.put("deferred",busy&&row.optInt("priority")<3);sorted.add(row);}}sorted.sort((a,b)->{int rank=Boolean.compare(a.optBoolean("read"),b.optBoolean("read"));if(rank==0)rank=Integer.compare(b.optInt("priority"),a.optInt("priority"));return rank==0?Long.compare(b.optLong("at"),a.optLong("at")):rank;});for(JSONObject row:sorted)out.put(row);return new JSONObject().put("items",out).put("enabled",c.getSharedPreferences("notification_review",0).getBoolean("enabled",false)).put("busy",busy).put("stateFresh",fresh);}
 static synchronized void mark(Context c,String id,int revision)throws Exception{JSONObject store=ReviewStore.read(c,"notices");JSONArray rows=store.optJSONArray("items");if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(id.equals(row.getString("id"))){if(revision!=row.getInt("revision"))throw new IOException("通知が更新されています。開き直してください");row.put("read",true);ReviewStore.write(c,"notices",store);return;}}throw new IOException("通知がありません");}
 private NotificationReview(){}
}
